CREATE TABLE [jfy_gift] (
    [id] int NOT NULL,
    [gift_name] nvarchar(32) NOT NULL,
    [at_least_recharge_count] int NOT NULL DEFAULT 1,
    [comments] nvarchar(max) NOT NULL,
    [content] nvarchar(max) NOT NULL,
    [cost_price] decimal(10, 2) NULL DEFAULT NULL,
    [cover] nvarchar(255) NOT NULL,
    [covers] nvarchar(max) NOT NULL,
    [description] nvarchar(62) NOT NULL DEFAULT '',
    [express_type] nvarchar(max) NOT NULL,
    [gift_type] int NOT NULL,
    [has_props] bit NOT NULL DEFAULT 0,
    [is_limit_sell] tinyint NOT NULL DEFAULT 0,
    [limit_customer_tags] nvarchar(max) NOT NULL,
    [limit_sell_custom] tinyint NOT NULL DEFAULT 0,
    [limit_sell_cycle] nvarchar(32) NOT NULL DEFAULT '',
    [limit_sell_cycle_count] int NOT NULL,
    [limit_sell_type] tinyint NOT NULL,
    [market_price] decimal(10, 2) NOT NULL,
    [out_sn] nvarchar(255) NOT NULL,
    [props] nvarchar(max) NOT NULL,
    [skus] nvarchar(max) NOT NULL,
    [score_price] decimal(10, 2) NOT NULL,
    [stock] int NOT NULL,
    [create_at] datetime2(0) NOT NULL,
    [store_id] int NOT NULL,
    [status] int NULL DEFAULT 1,
    [view_count] int NOT NULL DEFAULT 0,
    [sell_count] int NULL DEFAULT 0,
    PRIMARY KEY ([id])
);
